-- Dane demo My DecoLab (fikcyjne). Uruchom w Supabase SQL Editor.
-- 1) Zaloz konto przez strone rejestracji, 2) wpisz jego e-mail ponizej, 3) Run.
do $$
declare v_email text := 'WPISZ_EMAIL_KONTA@example.com'; v_tenant uuid; v_cid bigint; v_ct uuid;
begin
  select (raw_app_meta_data->>'tenant_id')::uuid into v_tenant from auth.users where lower(email)=lower(v_email);
  if v_tenant is null then raise exception 'Nie znaleziono konta %', v_email; end if;
  update tenants set is_demo=true, trial_ends_at=null where id=v_tenant;
  delete from offers where tenant_id=v_tenant;
  delete from clients where tenant_id=v_tenant;
  delete from contacts where tenant_id=v_tenant;
end $$;
